// Checks the hand-written background program (src/back_colours.js) against the mechanical translation of the
// firmware's back_colours0.fpo (src/shaders/back_colours0.frag.glsl, generated by rsx2glsl from your extracted
// files): random inputs and texture contents, all four textures, the whole clock range.
// Usage: node app/tools/check_back_colours.mjs   (needs the extracted files; prints the largest difference)
import { readFileSync } from 'node:fs';
import { join } from 'node:path';
import { compileFragmentToJs, rgba8Sampler } from '../src/glsl2js.js';
import { backColour } from '../src/back_colours.js';

const APP = join(import.meta.dirname, '..');
const ref = new Function('return ' + compileFragmentToJs(readFileSync(join(APP, 'src', 'shaders', 'back_colours0.frag.glsl'), 'utf8')))();
let seed = 1;
const rnd = () => ((seed = (seed * 1103515245 + 12345) & 0x7fffffff) / 0x7fffffff);
let worst = 0, worstAt = null, n = 0;
for (let trial = 0; trial < 40; trial++) {
  const tex = [0, 1, 2, 3].map(() => { const px = new Uint8Array(64 * 32 * 4); for (let i = 0; i < px.length; i++) px[i] = Math.floor(rnd() * 256); return rgba8Sampler(px, 64, 32); });
  const inp = { dayTime: rnd() * 2400, nightTime: rnd() * 2400, monthTime: rnd() * 30, nightBrightness: rnd() * 0.6, nightDayBlend: rnd(), alpha: rnd() * 3 };
  const u = { u_DayTime: [inp.dayTime, 0, 0, 0], u_NightTime: [inp.nightTime, 0, 0, 0], u_MonthTime: [inp.monthTime, 0, 0, 0], u_NightBrightness: [inp.nightBrightness, 0, 0, 0],
    u_NightDayBlend: [inp.nightDayBlend, 0, 0, 0], u_Alpha: [inp.alpha, 0, 0, 0], uPI: [Math.PI, 0, 0, 0] };
  for (let k = 0; k < 200; k++) {
    const px = rnd(), py = rnd();
    const a = ref(u, { vTc0: [px, py, 0, 0] }, tex), b = backColour(px, py, inp, tex);
    for (let c = 0; c < 4; c++) { const d = Math.abs(a[c] - b[c]); if (d > worst) { worst = d; worstAt = { inp, px, py, c, ref: a[c], ours: b[c] }; } }
    n++;
  }
}
console.log(`${n} samples: largest difference ${worst.toExponential(2)}`, worst > 1e-4 ? JSON.stringify(worstAt) : '(same to float rounding)');
